   "text": "# yaml-language-server: $schema=https://rangka-os.github.io/rangka-os/schema/0.4/system.json\n# Layer 2: one file per installation. App files say what they need; this file decides how.\ndb: {driver: postgres, url: '${DATABASE_URL}', pool: 10, isolation: shared}\ncache: {driver: memory, max_mb: 64}\nqueue: {driver: postgres, workers: 4, retries: 3, dead_letter_after: 24h}\nscheduler: {driver: internal, timezone: Asia/Jakarta}\nrealtime: {driver: postgres, transports: [sse]}\nfiles: {driver: local, path: ./data/files, max_upload_mb: 25}\nsearch: {driver: postgres, vectors: false}\nnotify:\n  email: {driver: log, from: Kopi Senja <halo@kopisenja.id>}\n  push: {enabled: false, driver: log}\n  whatsapp: {enabled: true, connector: whatsapp_business}\nauth:\n  issuer: http://localhost:8080\n  session_ttl: 24h\n  two_factor: owners\n  clients:\n    - id: omilo\n      label: Omilo\n      redirect_uris: [http://localhost:3000/auth/callback]\n      public: true\n      scopes: [openid, profile, email, rangka.mcp]\nsecrets: {driver: env}\naudit: {enabled: true, retention_days: 365}\nobservability: {log_level: info, metrics: true}\n",
