   "text": "# yaml-language-server: $schema=https://rangka-os.github.io/rangka-os/schema/0.4/connector.json\nname: whatsapp_business\nlabel: {id: WhatsApp Business}\nversion: 1.0.0\nvendor: Meta WhatsApp Cloud API\ndocs: https://developers.facebook.com/docs/whatsapp/cloud-api\nauth:\n  type: token\n  fields:\n    - name: access_token\n      label: {id: Access token}\n      secret: true\n    - name: phone_number_id\n      label: {id: Phone number ID}\n    - name: app_secret\n      label: {id: App secret}\n      secret: true\n      help: {id: Dipakai untuk memeriksa tanda tangan webhook}\n    - name: verify_token\n      label: {id: Verify token}\n      secret: true\n      generate: true\ntriggers:\n  - name: message_received\n    label: {id: Pesan masuk}\n    via: webhook\n    verify:\n      challenge: hub.verify_token == auth.verify_token\n      signature:\n        header: X-Hub-Signature-256\n        alg: hmac-sha256\n        key: auth.app_secret\n    for_each: entry[].changes[].value.messages[]\n    emit:\n      message_id: item.id\n      from: item.from\n      text: item.text.body\n      profile_name: value.contacts[0].profile.name\n      at: item.timestamp\n  # Delivery receipts of messages we sent (sent, delivered, read, failed), so a reminder can be logged as delivered.\n  - name: message_status\n    label: {id: Status pesan terkirim}\n    via: webhook\n    verify:\n      signature:\n        header: X-Hub-Signature-256\n        alg: hmac-sha256\n        key: auth.app_secret\n    for_each: entry[].changes[].value.statuses[]\n    emit:\n      message_id: item.id\n      status: item.status\n      to: item.recipient_id\n      at: item.timestamp\n      error: item.errors[0].title\nactions:\n  - name: send_template\n    label: {id: Kirim pesan template}\n    request:\n      method: POST\n      url: https://graph.facebook.com/{api_version}/{auth.phone_number_id}/messages\n      headers: {Authorization: 'Bearer {auth.access_token}'}\n      body:\n        messaging_product: whatsapp\n        to: '{input.to}'\n        type: template\n        template:\n          name: '{input.template}'\n          language: {code: id}\n          components: '{input.components}'\n    input:\n      - {name: to, type: phone, required: true}\n      - {name: template, type: data, required: true}\n      - {name: components, type: json}\n    retry:\n      max: 5\n      backoff: exponential\n      on: [429, 500, 502, 503]\n    idempotency: input.idempotency_key\nsettings:\n  - {name: api_version, type: data, default: \"'v21.0'\"}\nlimits:\n  rate: 80/s per phone number\n  note: {id: Pesan template di luar jendela 24 jam dikenai biaya oleh Meta}\n",
